package desync

// P1 regressions: upstream `nfq/desync.c` and `nfqws.c` (bol-van/zapret v72.9,
// c849e55ef0f1c244206f5a05ff7b1ab41a3824ee) accept a zero-stage method standing
// alone (`syndata`, `synack`) and a zero stage followed directly by a second
// stage (`syndata,multidisorder`). `nfqws.c` consumes the zero token first and
// parses the remaining `mode[,mode2]` slots independently, so an absent first
// stage is a legal gap, not an error. These tests are behavioural: they reach
// CompileMethods, the compiled Rule and the real PlanTCP planner, and they
// assert the generated bytes/original verdicts instead of matching source text.

import (
	"testing"
)

func TestP1SparseStageGrammarAcceptance(t *testing.T) {
	accept := []struct {
		name    string
		methods []string
		network TransportMask
	}{
		// Standalone zero stage: nfqws parses mode0, leaves mode/mode2 empty.
		{"standalone syndata", []string{"syndata"}, TransportMaskTCP},
		{"standalone synack", []string{"synack"}, TransportMaskTCP},
		// Zero + second: mode0 plus the sole remaining mode slot, which the
		// downstream switch executes as the second stage when mode2 is none.
		{"zero and multidisorder", []string{"syndata", "multidisorder"}, TransportMaskTCP},
		{"zero and multisplit", []string{"synack", "multisplit"}, TransportMaskTCP},
		{"zero and fakeddisorder alias", []string{"synack", "disorder"}, TransportMaskTCP},
		// The pre-existing forms must stay accepted.
		{"first only", []string{"fake"}, TransportMaskTCP},
		{"second only", []string{"multisplit"}, TransportMaskTCP},
		{"first and second", []string{"fake", "multisplit"}, TransportMaskTCP},
		{"zero first second", []string{"synack", "fake", "fakeddisorder"}, TransportMaskTCP},
		{"zero first", []string{"syndata", "fake"}, TransportMaskTCP},
		{"udp fake", []string{"fake"}, TransportMaskUDP},
		{"udp tamper", []string{"tamper"}, TransportMaskUDP},
	}
	for _, testCase := range accept {
		methods, err := CompileMethods(testCase.methods, testCase.network)
		if err != nil {
			t.Fatalf("%s: %v rejected: %v", testCase.name, testCase.methods, err)
		}
		if len(methods) != len(testCase.methods) {
			t.Fatalf("%s: compiled %d of %d methods", testCase.name, len(methods), len(testCase.methods))
		}
		for index, name := range testCase.methods {
			if methods[index].Name != canonicalStageName(name) {
				t.Fatalf("%s: method %d = %s, want %s", testCase.name, index, methods[index].Name, canonicalStageName(name))
			}
		}
	}
	reject := []struct {
		name    string
		methods []string
		network TransportMask
	}{
		// Reversed order is still invalid: the second stage cannot precede the
		// first stage upstream, and a first stage cannot follow a second one.
		{"second then first", []string{"disorder", "fake"}, TransportMaskTCP},
		{"second then zero", []string{"multisplit", "syndata"}, TransportMaskTCP},
		{"first then zero", []string{"fake", "syndata"}, TransportMaskTCP},
		// Duplicate stages stay rejected (upstream rejects the same stage in
		// both remaining slots; a repeated zero stage is not a valid combo).
		{"duplicate zero", []string{"syndata", "synack"}, TransportMaskTCP},
		{"duplicate first", []string{"fake", "fake"}, TransportMaskTCP},
		{"duplicate second", []string{"multisplit", "multidisorder"}, TransportMaskTCP},
		// Unknown methods and unsupported transports stay rejected.
		{"unknown method", []string{"nonsense"}, TransportMaskTCP},
		{"zero on udp", []string{"synack"}, TransportMaskUDP},
		{"zero and second on udp", []string{"syndata", "multisplit"}, TransportMaskUDP},
		{"tcp first on udp", []string{"rst"}, TransportMaskUDP},
		{"udp second on tcp", []string{"udplen"}, TransportMaskTCP},
		{"no network", []string{"fake"}, 0},
	}
	for _, testCase := range reject {
		if _, err := CompileMethods(testCase.methods, testCase.network); err == nil {
			t.Fatalf("%s: %v accepted", testCase.name, testCase.methods)
		}
	}
}

func canonicalStageName(name string) string {
	if info, found := methodTable[name]; found {
		return info.name
	}
	return name
}

// TestP1ZeroSecondExecution pins the upstream execution contract for the ALT5
// rule `syndata,multidisorder`: the zero stage acts on the bare SYN and the
// unrelated second stage acts on the first data packet. Neither stage may be
// invented where upstream has none.
func TestP1ZeroSecondExecution(t *testing.T) {
	rule := mustTestRule(t, `{"enabled":true,"rules":[{"network":["tcp"],`+
		`"methods":["syndata","multidisorder"],"multidisorder":{"split_pos":["1"]}}]}`)
	zero, first, second := stageMethods(rule.Methods)
	if zero == nil || zero.Name != "syndata" {
		t.Fatalf("zero stage = %+v", zero)
	}
	if first != nil {
		t.Fatalf("an absent first stage must stay absent, got %+v", first)
	}
	if second == nil || second.Name != "multidisorder" {
		t.Fatalf("second stage = %+v", second)
	}

	// A bare SYN reaches only the zero stage: one 16-byte fake SYN with the
	// original's flags, and the original is suppressed after the replacement.
	syn := buildIPv4TCP(t, nil, 7000, tcpFlagSYN)
	batch, err := PlanTCP(rule, syn, nil, 0, Facts{})
	if err != nil {
		t.Fatal(err)
	}
	if len(batch.Packets) != 1 || batch.Original != VerdictDrop {
		t.Fatalf("syndata stage mismatch: %d packets, original %v", len(batch.Packets), batch.Original)
	}
	generated, err := ParsePacket(batch.Packets[0])
	if err != nil {
		t.Fatal(err)
	}
	if len(generated.Payload) != 16 || generated.TCPFlags != tcpFlagSYN {
		t.Fatalf("syndata payload/flags mismatch: %d bytes, flags %x", len(generated.Payload), generated.TCPFlags)
	}
	if generated.TCPSeq != syn.TCPSeq {
		t.Fatalf("syndata sequence = %d, want original %d", generated.TCPSeq, syn.TCPSeq)
	}

	// The first data packet must not run the (absent) first stage but must run
	// the second stage: the payload is split into ordered segments that
	// reassemble to the original bytes, and the unsplit original is not also
	// forwarded.
	payload := []byte("0123456789abcdef")
	data := buildIPv4TCP(t, payload, 7001, tcpFlagACK|tcpFlagPSH)
	dataBatch, err := PlanTCP(rule, data, payload, 0, Facts{MessageLength: len(payload)})
	if err != nil {
		t.Fatal(err)
	}
	if dataBatch.Original == VerdictPass {
		t.Fatal("multidisorder without a first stage forwarded the original unchanged")
	}
	if len(dataBatch.Packets) < 2 {
		t.Fatalf("multidisorder produced %d segments", len(dataBatch.Packets))
	}
	// multidisorder transmits the segments out of order on purpose, so
	// reassemble by sequence offset rather than by capture order.
	reassembled := make([]byte, len(payload))
	covered := make([]bool, len(payload))
	for _, raw := range dataBatch.Packets {
		segment, parseErr := ParsePacket(raw)
		if parseErr != nil {
			t.Fatal(parseErr)
		}
		if len(segment.Payload) == 0 {
			continue
		}
		offset := int(segment.TCPSeq - data.TCPSeq)
		if offset < 0 || offset+len(segment.Payload) > len(reassembled) {
			t.Fatalf("segment at offset %d with %d bytes is outside the original payload", offset, len(segment.Payload))
		}
		copy(reassembled[offset:], segment.Payload)
		for index := offset; index < offset+len(segment.Payload); index++ {
			covered[index] = true
		}
	}
	for index, ok := range covered {
		if !ok {
			t.Fatalf("segment coverage missing byte %d", index)
		}
	}
	if string(reassembled) != string(payload) {
		t.Fatalf("segments reassemble to %q, want %q", reassembled, payload)
	}
}

// TestP1StandaloneSyndataKeepsLaterPayloadOrdinary pins the ALT7 rule
// `syndata`: a SYN-only desync. Later payload must stay ordinary (no invented
// fake/split stage) and must be forwarded unchanged.
func TestP1StandaloneSyndataKeepsLaterPayloadOrdinary(t *testing.T) {
	rule := mustTestRule(t, `{"enabled":true,"rules":[{"network":["tcp"],"methods":["syndata"]}]}`)
	syn := buildIPv4TCP(t, nil, 9000, tcpFlagSYN)
	batch, err := PlanTCP(rule, syn, nil, 0, Facts{})
	if err != nil {
		t.Fatal(err)
	}
	if len(batch.Packets) != 1 || batch.Original != VerdictDrop {
		t.Fatalf("standalone syndata SYN action mismatch: %d packets, original %v", len(batch.Packets), batch.Original)
	}
	payload := []byte("hello")
	data := buildIPv4TCP(t, payload, 9001, tcpFlagACK|tcpFlagPSH)
	dataBatch, err := PlanTCP(rule, data, payload, 0, Facts{MessageLength: len(payload)})
	if err != nil {
		t.Fatal(err)
	}
	if len(dataBatch.Packets) != 0 || dataBatch.Original != VerdictPass {
		t.Fatalf("standalone syndata invented a payload stage: %d packets, original %v",
			len(dataBatch.Packets), dataBatch.Original)
	}
}

// TestP1SynAckPassesOriginal pins the other zero-stage method: `synack` injects
// a fake SYN|ACK ahead of the original and keeps the original's pass verdict,
// unlike syndata's suppress-after-replacement behaviour.
func TestP1SynAckPassesOriginal(t *testing.T) {
	rule := mustTestRule(t, `{"enabled":true,"rules":[{"network":["tcp"],`+
		`"methods":["synack"],"ttl":4}]}`)
	syn := buildIPv4TCP(t, nil, 1000, tcpFlagSYN)
	batch, err := PlanTCP(rule, syn, nil, 0, Facts{})
	if err != nil {
		t.Fatal(err)
	}
	if len(batch.Packets) != 1 || batch.Original != VerdictPass {
		t.Fatalf("standalone synack mismatch: %d packets, original %v", len(batch.Packets), batch.Original)
	}
	generated, err := ParsePacket(batch.Packets[0])
	if err != nil {
		t.Fatal(err)
	}
	if generated.TCPFlags != tcpFlagSYN|tcpFlagACK || generated.TTL != 4 {
		t.Fatalf("synack flags/ttl mismatch: %x %d", generated.TCPFlags, generated.TTL)
	}
}

// TestP1SyndataAppliedOnlyToPlainSYN pins the two upstream suppressions that
// must survive the grammar repair: a SYN carrying a TCP Fast Open option and a
// SYN that already carries data keep their ordinary behaviour, and the
// original is not suppressed.
func TestP1SyndataAppliedOnlyToPlainSYN(t *testing.T) {
	rule := mustTestRule(t, `{"enabled":true,"rules":[{"network":["tcp"],"methods":["syndata"]}]}`)

	fastOpen := buildIPv4TCP(t, nil, 2000, tcpFlagSYN)
	fastOpen.TCPOptions = []byte{34, 2}
	parseTCPOptions(fastOpen)
	if !fastOpen.HasFastOpen {
		t.Fatal("fixture did not carry a TCP fast open option")
	}
	batch, err := PlanTCP(rule, fastOpen, nil, 0, Facts{})
	if err != nil {
		t.Fatal(err)
	}
	if len(batch.Packets) != 0 || batch.Original != VerdictPass {
		t.Fatalf("syndata touched a fast-open SYN: %d packets, original %v", len(batch.Packets), batch.Original)
	}
	if batch.Reason == "" {
		t.Fatal("the fast-open suppression must stay visible in the batch reason")
	}

	withPayload := buildIPv4TCP(t, []byte("early"), 2001, tcpFlagSYN)
	batch, err = PlanTCP(rule, withPayload, nil, 0, Facts{})
	if err != nil {
		t.Fatal(err)
	}
	if len(batch.Packets) != 0 || batch.Original != VerdictPass {
		t.Fatalf("syndata touched a SYN that already carries data: %d packets, original %v",
			len(batch.Packets), batch.Original)
	}
}

// profileMode is one (transport, --dpi-desync=) pair from a pinned Flowseal
// profile. Only the desync grammar is recorded here; the payload/list file
// paths and operator selectors of the converted profiles stay in the private
// evidence tree.
type profileMode struct {
	transport string
	methods   string
}

