// TestP1FlowsealProfilesAccepted is the permanent all-22 acceptance matrix: every
// desync grammar the pinned profiles configure must compile for its transport.
func TestP1FlowsealProfilesAccepted(t *testing.T) {
	if len(flowsealProfiles) != 22 {
		t.Fatalf("profile table has %d entries, want all 22", len(flowsealProfiles))
	}
	names := make(map[string]bool, len(flowsealProfiles))
	hashes := make(map[string]bool, len(flowsealProfiles))
	grammars := 0
	for _, profile := range flowsealProfiles {
		if names[profile.name] {
			t.Fatalf("duplicate profile name %q", profile.name)
		}
		names[profile.name] = true
		if len(profile.sha) != 64 {
			t.Fatalf("%s: SHA-256 %q is not a full digest", profile.name, profile.sha)
		}
		if hashes[profile.sha] {
			t.Fatalf("duplicate source hash %q", profile.sha)
		}
		hashes[profile.sha] = true
		if len(profile.modes) == 0 {
			t.Fatalf("%s: no desync grammar recorded", profile.name)
		}
		for _, mode := range profile.modes {
			grammars++
			methods := splitDesyncGrammar(mode.methods)
			network := TransportMaskTCP
			if mode.transport == "udp" {
				network = TransportMaskUDP
			}
			if mode.transport == "both" {
				network = TransportMaskTCP | TransportMaskUDP
			}
			if _, err := CompileMethods(methods, network); err != nil {
				t.Fatalf("%s (%s, %s) rejected: %v", profile.name, mode.transport, mode.methods, err)
			}
		}
	}
	if grammars < 22 {
		t.Fatalf("only %d grammars enumerated", grammars)
	}
}

func splitDesyncGrammar(value string) []string {
	var methods []string
	current := ""
	for _, char := range value {
		if char == ',' {
			methods = append(methods, current)
			current = ""
			continue
		}
		current += string(char)
	}
	return append(methods, current)
}
